-- Invita Arte Studio - Datos demo completos para Supabase
-- Ejecutar después de supabase_schema.sql y actualizacion_crud_roles.sql.
-- No borra tus datos; usa upsert con IDs fijos para actualizar los registros demo.

on conflict (id) do update set title=excluded.title, category=excluded.category, style=excluded.style, package_type=excluded.package_type, base_price=excluded.base_price, description=excluded.description, features=excluded.features, accent=excluded.accent, preview_url=excluded.preview_url, is_active=excluded.is_active, updated_at=now();

on conflict (id) do update set tracking_code=excluded.tracking_code, client_name=excluded.client_name, email=excluded.email, phone=excluded.phone, event_type=excluded.event_type, package_type=excluded.package_type, template_id=excluded.template_id, event_title=excluded.event_title, honorees=excluded.honorees, event_date=excluded.event_date, event_time=excluded.event_time, location=excluded.location, notes=excluded.notes, guests=excluded.guests, urgent=excluded.urgent, status=excluded.status, total_amount=excluded.total_amount, updated_at=now();

on conflict (id) do update set preview_url=excluded.preview_url, notes=excluded.notes, status=excluded.status;

on conflict (id) do update set amount=excluded.amount, method=excluded.method, proof_url=excluded.proof_url, status=excluded.status;

on conflict (id) do update set guest_name=excluded.guest_name, guest_phone=excluded.guest_phone, attendance=excluded.attendance, companions=excluded.companions, notes=excluded.notes;

on conflict (id) do update set event_name=excluded.event_name, payload=excluded.payload, created_at=excluded.created_at;

